/bin/bash -lc "python - <<'PY'
import cv2, glob, os
for p in glob.glob('*'):
 try:
  c=cv2.VideoCapture(p)
  if c.isOpened() and int(c.get(cv2.CAP_PROP_FRAME_COUNT))>0:
   print(p, 'frames', int(c.get(cv2.CAP_PROP_FRAME_COUNT)), 'fps', c.get(cv2.CAP_PROP_FPS), 'size', int(c.get(cv2.CAP_PROP_FRAME_WIDTH)), int(c.get(cv2.CAP_PROP_FRAME_HEIGHT)), 'dur', c.get(cv2.CAP_PROP_FRAME_COUNT)/c.get(cv2.CAP_PROP_FPS))
  c.release()
 except: pass
PY"
